<?php require 'config.php';require 'auth.php';requireLogin();$pageTitle='Kategori';$categories=read_data('categories');$items=read_data('items');foreach($categories as &$c)$c['total_items']=count(array_filter($items,fn($i)=>(int)$i['category_id']===(int)$c['id']));unset($c);include 'header.php';?><section class="page-heading"><div><h1>Kategori Barang</h1></div><a href="category_add.php" class="btn btn-primary">＋ Tambah Kategori</a></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Deskripsi</th><th>Jumlah Barang</th><th>Aksi</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['description']??'-')?></td><td><?=$c['total_items']?></td><td><a class="btn btn-secondary btn-sm" href="category_edit.php?id=<?=$c['id']?>">Edit</a><a class="btn btn-danger btn-sm" href="category_delete.php?id=<?=$c['id']?>" onclick="return confirm('Hapus kategori ini?')">Hapus</a></td></tr><?php endforeach;?></tbody></table></div></section><?php include 'footer.php';?>